import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/sheets/data-validation-dropdown.png",l="/docs/images/sheets/data-validation-panel-mobile.png",b=JSON.parse('{"title":"Add checkboxes, dropdowns, and validation","description":"Add checkboxes, dropdown lists, and date pickers to cells, and flag or block values that break a rule.","frontmatter":{"title":"Add checkboxes, dropdowns, and validation","description":"Add checkboxes, dropdown lists, and date pickers to cells, and flag or block values that break a rule.","type":"how-to"},"headers":[],"relativePath":"sheets/data-validation.md","filePath":"sheets/data-validation.md"}'),r={name:"sheets/data-validation.md"};function i(d,e,c,h,p,g){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="add-checkboxes-dropdowns-and-validation" tabindex="-1">Add checkboxes, dropdowns, and validation <a class="header-anchor" href="#add-checkboxes-dropdowns-and-validation" aria-label="Permalink to &quot;Add checkboxes, dropdowns, and validation&quot;">​</a></h1><p>Add checkboxes, dropdown lists, and date pickers to cells, and flag or block values that break a rule.</p><p>The control is the cell&#39;s own value, so it keeps working when you sort, filter, copy, or use the cell in a formula.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. Viewers see the controls but can&#39;t change them.</li><li>Rules belong to one tab. Each tab has its own list.</li></ul></div><h2 id="add-a-dropdown-list" tabindex="-1">Add a dropdown list <a class="header-anchor" href="#add-a-dropdown-list" aria-label="Permalink to &quot;Add a dropdown list&quot;">​</a></h2><ol><li><p>Open the sheet and select the cells, for example <strong>C2:C20</strong>.</p></li><li><p>Click <strong>Data validation</strong> (the checklist icon) in the toolbar. You can also right-click the selection and select <strong>Data validation</strong>.</p></li><li><p>The panel opens on a new, <strong>Unsaved</strong> rule for your selection, with <strong>Criteria</strong> set to <strong>Dropdown</strong>.</p></li><li><p>Under <strong>Options (one per line)</strong>, type each choice on its own line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>To do</span></span>
<span class="line"><span>In progress</span></span>
<span class="line"><span>Done</span></span></code></pre></div></li><li><p>Click <strong>Done</strong>.</p></li></ol><p>Each cell now shows a dropdown arrow. Click the arrow, or press <code>Option+↓</code> / <code>Alt+↓</code>, to pick an option.</p><p><strong>Done</strong> stays unavailable until the list has at least one option. To discard the rule, click <strong>Cancel</strong> or close the panel.</p><p>To keep the rule but hide the arrows, turn off <strong>Show dropdown arrow</strong>.</p><p><img src="`+s+'" alt="Data validation panel with an unsaved dropdown rule, three options, and the Done button"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap <strong>More formatting options</strong> (⋮) at the right end of the toolbar, then select <strong>Data validation</strong>. You can also touch and hold the selection and select <strong>Data validation</strong>.</p><p><img src="'+l+'" alt="Data validation panel covering the screen on a phone with a dropdown rule and Done button"></p><h2 id="add-checkboxes" tabindex="-1">Add checkboxes <a class="header-anchor" href="#add-checkboxes" aria-label="Permalink to &quot;Add checkboxes&quot;">​</a></h2><ol><li>Select the cells and click <strong>Data validation</strong>.</li><li>Set <strong>Criteria</strong> to <strong>Checkbox</strong>.</li><li>Click <strong>Done</strong>.</li></ol><p>Each cell becomes a checkbox that stores <code>TRUE</code> or <code>FALSE</code>. Click a box to toggle it, or select several and press <code>Space</code> to toggle them together. Formulas such as <code>=COUNTIF(B2:B20, TRUE)</code> count the checked boxes.</p><h2 id="validate-dates-numbers-or-text" tabindex="-1">Validate dates, numbers, or text <a class="header-anchor" href="#validate-dates-numbers-or-text" aria-label="Permalink to &quot;Validate dates, numbers, or text&quot;">​</a></h2><ol><li>Select the cells and click <strong>Data validation</strong>.</li><li>Set <strong>Criteria</strong> to <strong>Date</strong>, <strong>Number</strong>, or <strong>Text</strong>.</li><li>Pick a <strong>Condition</strong> and enter its value. &quot;Between&quot; conditions take two values.</li><li>Click <strong>Done</strong>.</li></ol><table tabindex="0"><thead><tr><th>Criteria</th><th>Conditions</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>is a valid date, date is, date is before, date is on or before, date is after, date is on or after, date is between, date is not between</td></tr><tr><td><strong>Number</strong></td><td>is a valid number, is equal to, is not equal to, greater than, greater than or equal to, less than, less than or equal to, between, not between</td></tr><tr><td><strong>Text</strong></td><td>contains, does not contain, is exactly, is valid email, is valid URL</td></tr></tbody></table><p>To fill a date cell from a calendar, double-click it.</p><h2 id="choose-what-happens-to-invalid-data" tabindex="-1">Choose what happens to invalid data <a class="header-anchor" href="#choose-what-happens-to-invalid-data" aria-label="Permalink to &quot;Choose what happens to invalid data&quot;">​</a></h2><p>Dropdown, date, number, and text rules have an <strong>If the data is invalid</strong> setting:</p><ul><li><strong>Show a warning</strong>: the value is kept and the cell gets a small red triangle in its top-right corner. Point at the cell to see why, for example <code>Invalid entry — must be one of: To do, In progress, Done</code>.</li><li><strong>Reject the input</strong>: a typed value that breaks the rule isn&#39;t saved. A message explains why, and the cell keeps its previous value.</li></ul><p>A formula whose result breaks the rule is flagged with the red triangle, not rejected. Pasted values are flagged the same way.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>Show a warning</strong> while you clean up existing data, then switch to <strong>Reject the input</strong> once the column should only hold valid values.</p></div><h2 id="edit-or-remove-a-rule" tabindex="-1">Edit or remove a rule <a class="header-anchor" href="#edit-or-remove-a-rule" aria-label="Permalink to &quot;Edit or remove a rule&quot;">​</a></h2><ol><li>Select a cell the rule covers and click <strong>Data validation</strong>. The panel opens on that rule.</li><li>Change the criteria, options, or range. To change the range, type it under <strong>Apply to range</strong> (for example <code>B2:B100, D2:D100</code>) and click <strong>Apply</strong>, or click <strong>Use selected range</strong>.</li><li>To remove the rule, click <strong>✕</strong> on its card.</li></ol><p>Changes to an existing rule save as you make them. When you remove a rule, its cells go back to plain values.</p><h3 id="add-another-rule" tabindex="-1">Add another rule <a class="header-anchor" href="#add-another-rule" aria-label="Permalink to &quot;Add another rule&quot;">​</a></h3><p>Click <strong>Add</strong> in the panel. A new dropdown rule appears for the current selection, and you edit it the same way.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Checkbox rules have no invalid-data setting, and their cells are never flagged.</li><li>Clicking the grid closes the panel. Select the cells before you open it.</li><li>Data validation isn&#39;t available on data source or lakehouse tabs.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/conditional-formatting.html">Conditional formatting</a> to color cells by their values.</li><li><a href="/docs/sheets/formulas.html">Formulas</a> to count checkboxes or dropdown choices.</li><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard shortcuts</a> for <code>Space</code> and <code>Alt+↓</code>.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to give teammates edit access.</li></ul>',34)])])}const m=t(r,[["render",i]]);export{b as __pageData,m as default};
